      const bits=[];
      const code=Number(r.weather_code);
      if(Number.isFinite(code)){const w=wmoWord(code);bits.push(`${wmoIcon(code)} ${esc(w)}`);}
      const temp=formatTemp(r.temp);
      if(temp!=='—')bits.push(esc(temp));
