    // CL-CI-13: the modal subtitle must describe the ACTUAL hourly data window,
    // not a hardcoded stale constant. The legacy pipeline fetches past 24h +
    // 168h forecast (get_weather.py past_hours/forecast_hours); the real span
    // of the loaded spot payload is measured here and substituted into the
    // {p}/{f} template so the copy follows the data if the window changes again.
    const HOURLY_WINDOW_DEFAULT={past:24,future:168};
    let modalHourlyWindow={...HOURLY_WINDOW_DEFAULT};
    function hourSpan(isoA,isoB){const a=Date.parse(isoA),b=Date.parse(isoB);return (Number.isFinite(a)&&Number.isFinite(b))?Math.round((b-a)/36e5):null;}
    function updateModalHourlyWindow(spot){
      const rows=(spot&&spot.hourly_forecast)||[];
      if(rows.length<2)return;
      const now=Date.now();
      const past=hourSpan(rows[0].time_utc||rows[0].time,new Date(now).toISOString());
      const future=hourSpan(new Date(now).toISOString(),rows[rows.length-1].time_utc||rows[rows.length-1].time);
      if(past===null||future===null||future<=0)return;
      modalHourlyWindow={past:Math.max(0,past),future};
    }
