    function distanceToSpotKm(spot){
      if(!userLocation)return null;
      const lat=Number(spot?.lat),lon=Number(spot?.lon);
      if(!Number.isFinite(lat)||!Number.isFinite(lon))return null;
      const toRad=value=>value*Math.PI/180;
      const dLat=toRad(lat-userLocation.lat),dLon=toRad(lon-userLocation.lon);
      const a=Math.sin(dLat/2)**2+Math.cos(toRad(userLocation.lat))*Math.cos(toRad(lat))*Math.sin(dLon/2)**2;
      return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
    }
    function sortRows(rows,mode){
      const sortMode=mode||currentSortMode;
      rows.forEach(row=>row.distance=distanceToSpotKm(row.spot));
      rows.sort((a,b)=>{
        if(sortMode==='region')return compareGeographic(a,b);
        if(sortMode==='hours_desc'){
          const av=v2HoursSortValue(a.spot),bv=v2HoursSortValue(b.spot);
          if(av===null&&bv!==null)return 1;
          if(bv===null&&av!==null)return -1;
          if(av!==null&&bv!==null&&av!==bv)return bv-av;
          return compareGeographic(a,b);
        }
        // CL-UI-66: 「最近可拍」 — the earliest next qualifying window first.
        // Today's remaining hours rank by clock time; a spot with none left
        // today falls back to its next-day window; no known window sinks to
        // the end. Ties keep the region order.
        if(sortMode==='next_window'){
          const av=clui66NextWindowValue(a.spot),bv=clui66NextWindowValue(b.spot);
          if(av!==bv)return av-bv;
          return compareGeographic(a,b);
        }
        // CL-DATA-80: 「綜合分」 — S_rank (AGLI^0.35×S_quality^0.65) of the
        // place's best qualifying subject, high to low. Opt-in sort option;
        // the default sort is unchanged pending owner acceptance.
        if(sortMode==='srank_desc'){
          const av=v2SRankSortValue(a.spot),bv=v2SRankSortValue(b.spot);
          if(av===null&&bv!==null)return 1;
          if(bv===null&&av!==null)return -1;
          if(av!==null&&bv!==null&&av!==bv)return bv-av;
          return compareGeographic(a,b);
        }
        if(sortMode==='distance_near'||sortMode==='distance_far'){
          const av=a.distance,bv=b.distance;
          if(av===null&&bv!==null)return 1;
          if(bv===null&&av!==null)return -1;
          if(av!==null&&bv!==null&&av!==bv)return sortMode==='distance_near'?av-bv:bv-av;
          return compareGeographic(a,b);
        }
        return compareGeographic(a,b);
      });
      return rows;
    }
