    // 「最近可拍」 sort value: minutes until the next qualifying window
    // (today's remaining hours rank by clock time; a later day ranks by day
    // offset × 1440 + minutes; no known window = Infinity, sinks to the end).
    function clui66NextWindowValue(spot){
      const place=v2PlaceForSpot(spot);
      const best=place?v2BestForSpot(place,spot.timezone):null;
      if(!best)return Number.POSITIVE_INFINITY;
      const now=v2LocalNow(spot.timezone);
      const first=(best.hoursList||[]).map(t=>String(t||'').slice(-5)).filter(t=>/^([01]\d|2[0-3]):[0-5]\d$/.test(t)).sort()[0];
      if(first&&now)return Number(first.slice(0,2))*60+Number(first.slice(3,5));
      const nx=best.nextLocal?v2ParseLocalStamp(best.nextLocal):null;
      if(nx&&now){
        const dayDiff=Math.round((new Date(nx.date+'T00:00:00Z')-new Date(now.date+'T00:00:00Z'))/86400000);
        if(dayDiff>=0)return dayDiff*1440+nx.minutes;
      }
      return Number.POSITIVE_INFINITY;
    }

    // CL-UI-91 (owner ruling): the subject chip narrows ONLY the ✓推薦 layer.
    // ○可拍 (general baseline passes) and ✗不宜 (general baseline fails) are
    // chip-INDEPENDENT classifications — a shootable/not_recommended row
