      const elev=[];
      if(spot.elevation!=null)elev.push(`${esc(d().prov_elev_camera)} ${esc(spot.elevation)} m`);
      else if(spot.api_elevation!=null)elev.push(`${esc(d().prov_elev_api)} ${esc(spot.api_elevation)} m`);
      if(run&&run.grid&&run.grid.elevation_m!=null)elev.push(`${esc(d().prov_elev_grid)} ${esc(run.grid.elevation_m)} m`);
      const coord=spot.coordinate_source?`${esc(d().prov_coord_label)}：${esc(spot.coordinate_source)}${spot.coordinate_confidence?`（${esc(d().prov_confidence_label)} ${esc(provConfLabel(spot.coordinate_confidence))}）`:''}`:esc(d().prov_coord_unknown);
      rows.push(`<div class="prov-row"><span class="prov-k">${esc(d().prov_elev_label)}</span><span class="prov-v">${elev.length?elev.join(' · ')+'<br>':''}${coord}</span></div>`);
