      rows.push(`<div class="prov-row"><span class="prov-k">${esc(d().prov_tz_label)}</span><span class="prov-v">${esc(off)}（${esc(spot.timezone||'')}）— ${esc(d().prov_tz_note)}</span></div>`);
      return rows.join('');
