        const V2_METRIC_UNITS={cloud_cover_low:'%',cloud_cover_mid:'%',cloud_cover_high:'%',cloud_cover_mid_and_high:'%',cloud_cover_total:'%',relative_humidity_2m:'%',relative_humidity_925hpa:'%',relative_humidity_850hpa:'%',relative_humidity_700hpa:'%',relative_humidity_600hpa:'%',moon_illumination_fraction:'%',visibility:'km',precipitation:'mm',wind_speed_10m:'m/s',wind_speed_850hpa:'m/s',wind_speed_600hpa:'m/s',lcl_height_m_agl:'m',temperature_delta_850_925_c:'°C',temperature_delta_700_600_c:'°C'};
        const unitTxt=((cond.unit?' '+cond.unit:'').trim())||V2_METRIC_UNITS[cond.metric]||'';
        if(!unitTxt)return t.v2_cond_now+' '+(cond.verdict==='PASS'?t.eval2_ok:cond.verdict==='FAIL'?t.eval2_bad:t.eval2_unk);
        return t.v2_cond_now+' '+v2FmtNum(v)+' '+unitTxt+' · '+gapTxt;
